{
  "definition": {
    "id": "PM_ORDERS",
    "title": "Postman Orders",
    "description": "Created by the Postman collection",
    "folder": "Postman",
    "connectionId": "pm_mongo",
    "collection": "orders",
    "queryLanguage": "aggregation-json",
    "querySource": "[{\"$match\": {\"Branch\": {\"$param\": \"Branch\"}}}, {\"$project\": {\"_id\": 0, \"Name\": 1, \"Branch\": 1, \"Amount\": 1, \"CNIC\": 1}}]",
    "columns": [
      "Name",
      "Branch",
      "Amount",
      "CNIC"
    ],
    "formats": [
      "pdf",
      "xlsx",
      "csv"
    ],
    "defaultFormat": "pdf",
    "parameters": [
      {
        "name": "Branch",
        "type": "string",
        "label": "Branch",
        "required": true,
        "allowedValues": [
          "LHR",
          "KHI",
          "ISB"
        ]
      },
      {
        "name": "CNIC",
        "type": "string",
        "label": "CNIC",
        "required": false,
        "sensitive": true
      }
    ],
    "design": {
      "bands": {
        "columnHeader": {
          "height": 20,
          "elements": [
            {
              "type": "staticText",
              "x": 0,
              "y": 0,
              "width": 160,
              "height": 16,
              "text": "Name"
            },
            {
              "type": "staticText",
              "x": 170,
              "y": 0,
              "width": 100,
              "height": 16,
              "text": "Amount"
            }
          ]
        },
        "detail": {
          "height": 20,
          "elements": [
            {
              "type": "textField",
              "x": 0,
              "y": 0,
              "width": 160,
              "height": 16,
              "expression": "$F{Name}"
            },
            {
              "type": "textField",
              "x": 170,
              "y": 0,
              "width": 100,
              "height": 16,
              "expression": "$F{Amount}"
            }
          ]
        }
      }
    }
  }
}

