const mine = pm.response.json().datasets.filter(d => [pm.environment.get('dsOrders'), pm.environment.get('dsBranches')].includes(d.id));
const tries = Number(pm.environment.get('analyticsTries') || 0);
if (mine.some(d => d.status !== 'ready' && d.status !== 'failed') && tries < 30) { pm.environment.set('analyticsTries', tries + 1); postman.setNextRequest(pm.info.requestName); }
else { pm.environment.unset('analyticsTries'); pm.test('both imported', function () { mine.forEach(d => pm.expect(d.status).to.eql('ready')); }); }
